HF_TOKEN = os.getenv("HF_TOKEN")

def create_or_get_secret(name: str, value: str | None, label: str) -> HelixSecretResponse | None:
    if not value:
        print(f"{label} is not set - skipping setting secret")
        return None
    try:
        secret = client.secrets.create_secret(
            body=HelixSecretCreateRequest(name=name, value=SecretStr(value)),
        ).data()
        print(f"Created secret: {name}")
        return secret
    except ConflictError:
        print(f"Secret '{name}' already exists, continuing...")
        return client.secrets.get_secret(name=name).data()


hf_secret = create_or_get_secret("hf-token", HF_TOKEN, "HF_TOKEN")

check = max_wait_time_checker(1800, "Deployment")
while True:
    check()
    deployment_status = client.models.get_deployment(name=deployment.name).data()
    clear_output(wait=True)
    print(f"Deployment status: {deployment_status.status}")
    if deployment_status.status in ("READY", "RUNNING"):
        if not client.models.wait_for_gateway(deployment.name, workspace="default", timeout=60):
            raise RuntimeError("Inference gateway did not become ready")
        break
    if deployment_status.status in ("FAILED", "ERROR", "TERMINATED", "LOST"):
        raise RuntimeError(f"Deployment failed with status: {deployment_status.status}")
    time.sleep(15)
